Method.Source:
    public str processExpressionCommon(Common _common, DocuTypeId _typeId = DocuType::typeNote())
    {
        DocuRef		dRef;
		str			ret;

        while select dRef
            where dRef.RefCompanyId		== _common.dataAreaId
            && dRef.RefTableId          == _common.TableId
            && dRef.RefRecId			== _common.RecId
			&& (dRef.TypeId				== _typeId || !_typeId)
            && dRef.Restriction			== DocuRestriction::Internal
        {
            ret += (ret ? TFMConstants::lineBreak() : '' ) + dRef.Name + ':' + TFMConstants::lineBreak() + dRef.Notes;
        }

        return ret;
    }

	[SysObsolete]
    public str processExpressionValue(str _value)
    {
